#!/usr/bin/env python3
"""Materialize the auditable plain-text Build123d model and exact validator."""
from __future__ import annotations
import base64
import gzip
from pathlib import Path

ROOT = Path(__file__).resolve().parent
FILES = {
    "dilemma_tenting_puck_family.py": "",
    "validate_dilemma_tenting_puck.py": "",
}

for name, encoded in FILES.items():
    target = ROOT / name
    target.write_bytes(gzip.decompress(base64.b64decode(encoded)))
    print(f"materialized {target.name}: {target.stat().st_size} bytes")
